document.addEventListener("click",async event=>{const button=event.target.closest("[data-playing-now]");if(!button)return;event.preventDefault();event.stopPropagation();const item=state.items.find(entry=>String(entry.id)===button.dataset.playingNow);if(!item)return;button.disabled=true;try{const status=button.dataset.playingAction==="remove"?"planned":"in_progress",body=await api(`/api/library/${item.id}`,{method:"PATCH",body:JSON.stringify({status})});Object.assign(item,body.item);document.querySelectorAll("[data-card-menu-panel]").forEach(panel=>panel.hidden=true);toast(status==="in_progress"?"Adicionado a Jogando agora.":"Removido de Jogando agora.");render()}catch(error){button.disabled=false;toast(error.message)}});
function showListEditor(existing=null){document.querySelector(".list-modal")?.remove();const overlay=document.createElement("div");overlay.className="list-modal";overlay.innerHTML=`<form class="list-dialog"><header><div><span class="eyebrow">Fila personalizada</span><h2>${existing?"Editar lista":"Nova lista"}</h2></div><button type="button" data-close>${icon("close")}</button></header><label>Nome<input name="name" maxlength="80" value="${esc(existing?.name||"")}" placeholder="Ex.: Ver depois" required autofocus></label><label>Descrição<input name="description" maxlength="300" value="${esc(existing?.description||"")}" placeholder="Opcional"></label><label>Tipo<select name="category">${[["mixed","Qualquer obra"],["movie","Filmes"],["tv","Séries"],["anime","Animes"],["game","Jogos"]].map(([v,l])=>`<option value="${v}" ${existing?.category===v?"selected":""}>${l}</option>`).join("")}</select></label><fieldset><legend>Ícone</legend><div class="list-icon-picker">${listIcons.map((v,i)=>`<button type="button" data-list-icon="${v}" class="${(existing?.icon||"playlist_play")===v?"selected":""}">${icon(v)}</button>`).join("")}</div></fieldset><fieldset><legend>Cor</legend><div class="list-color-picker">${listColors.map(v=>`<button type="button" data-list-color="${v}" class="${(existing?.color||"#3b82f6")===v?"selected":""}" style="--list-color:${v}"></button>`).join("")}</div></fieldset><div class="list-dialog-actions">${existing?`<button type="button" class="danger" data-delete-list>Excluir</button>`:""}<button type="button" data-close>Cancelar</button><button class="primary" type="submit">${existing?"Salvar":"Criar lista"}</button></div></form>`;document.body.append(overlay);let selectedIcon=existing?.icon||"playlist_play",selectedColor=existing?.color||"#3b82f6";overlay.querySelectorAll("[data-close]").forEach(x=>x.onclick=()=>overlay.remove());overlay.querySelectorAll("[data-list-icon]").forEach(x=>x.onclick=()=>{selectedIcon=x.dataset.listIcon;overlay.querySelectorAll("[data-list-icon]").forEach(y=>y.classList.toggle("selected",y===x))});overlay.querySelectorAll("[data-list-color]").forEach(x=>x.onclick=()=>{selectedColor=x.dataset.listColor;overlay.querySelectorAll("[data-list-color]").forEach(y=>y.classList.toggle("selected",y===x))});overlay.querySelector("form").onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget),payload={name:data.get("name"),description:data.get("description"),category:data.get("category"),icon:selectedIcon,color:selectedColor};try{const body=await api(existing?`/api/lists/${existing.id}`:"/api/lists",{method:existing?"PATCH":"POST",body:JSON.stringify(payload)});if(existing)Object.assign(existing,body.list);else state.lists.push(body.list);overlay.remove();render()}catch(error){toast(error.message)}};overlay.querySelector("[data-delete-list]")?.addEventListener("click",async()=>{if(!confirm("Excluir esta lista e as tarefas vinculadas?"))return;await api(`/api/lists/${existing.id}`,{method:"DELETE"});state.lists=state.lists.filter(x=>x.id!==existing.id);state.activeList=null;state.view="home";overlay.remove();render()})}
function enhanceListButtons(){document.querySelectorAll("[data-favorite]").forEach(favorite=>{if(favorite.parentElement?.querySelector("[data-list-add]"))return;const button=document.createElement("button");button.className="icon-btn";button.dataset.listAdd=favorite.dataset.favorite;button.title="Adicionar a uma lista";button.innerHTML=icon("playlist_add");button.onclick=()=>addItemToList(button.dataset.listAdd);favorite.before(button)})}
function bindCustomListPage(){const page=document.querySelector(".list-page");if(!page||page.dataset.bound)return;page.dataset.bound="1";page.querySelector("[data-edit-list]")?.addEventListener("click",()=>showListEditor(state.activeList.list));page.querySelectorAll("[data-queue-remove]").forEach(x=>x.onclick=async()=>{await api(`/api/lists/${state.activeList.list.id}/items/${x.dataset.queueRemove}`,{method:"DELETE"});state.activeList.items=state.activeList.items.filter(i=>String(i.id)!==x.dataset.queueRemove);const l=state.lists.find(v=>v.id===state.activeList.list.id);if(l)l.itemCount--;render()});page.querySelectorAll("[data-queue-complete]").forEach(x=>x.onclick=async()=>{const item=state.activeList.items.find(i=>String(i.id)===x.dataset.queueComplete),completed=item.status!=="completed";await api(`/api/lists/${state.activeList.list.id}/items/${item.id}/complete`,{method:"PATCH",body:JSON.stringify({completed})});item.status=completed?"completed":"planned";const original=state.items.find(i=>i.id===item.id);if(original)original.status=item.status;render()});let dragged=null;page.querySelectorAll("[data-queue-id]").forEach(row=>{row.ondragstart=()=>{dragged=row;row.classList.add("dragging")};row.ondragend=()=>{row.classList.remove("dragging");dragged=null};row.ondragover=e=>{e.preventDefault();if(!dragged||dragged===row)return;const box=row.getBoundingClientRect();row.parentElement.insertBefore(dragged,e.clientY<box.top+box.height/2?row:row.nextSibling)};row.ondrop=async e=>{e.preventDefault();const ids=[...row.parentElement.children].map(x=>Number(x.dataset.queueId));state.activeList.items=ids.map(id=>state.activeList.items.find(i=>i.id===id));await api(`/api/lists/${state.activeList.list.id}/reorder`,{method:"POST",body:JSON.stringify({itemIds:ids})});render()}})}
function customListContent(){const {list,items}=state.activeList;return `<section class="list-page"><header><div><span class="list-heading-icon" style="--list-color:${esc(list.color)}">${icon(list.icon)}</span><div><span class="eyebrow">Lista ordenada</span><h1>${esc(list.name)}</h1><p>${esc(list.description||"Arraste as obras para definir a próxima da fila.")}</p></div></div><button data-edit-list>${icon("edit")} Editar</button></header>${items.length?`<div class="queue" data-queue>${items.map((item,index)=>`<article class="queue-item" draggable="true" data-queue-id="${item.id}"><span class="queue-handle">${icon("drag_indicator")}</span><strong>${index+1}</strong>${item.poster_url?`<img src="${esc(item.poster_url)}" alt="">`:""}<div><h3>${esc(item.title)}</h3><p>${itemCategory(item)==="game"?"Jogar":"Assistir"} · ${esc(item.release_year||"")}</p></div><button data-queue-complete="${item.id}" class="${item.status==="completed"?"done":""}" title="Marcar como concluído">${icon(item.status==="completed"?"check_circle":"radio_button_unchecked")}</button><button data-queue-remove="${item.id}" title="Remover da lista">${icon("close")}</button></article>`).join("")}</div>`:`<div class="empty">${icon("playlist_add")}<h3>Esta lista está vazia</h3><p>Use o botão de lista nos cards para adicionar obras.</p></div>`}</section>`}
async function addItemToList(itemId){if(!state.lists.length)return showListEditor();const modal=document.createElement("div");modal.className="list-modal";modal.innerHTML=`<div class="list-dialog compact"><header><h2>Adicionar à lista</h2><button data-close>${icon("close")}</button></header><div class="list-choices">${state.lists.map(l=>`<button data-pick-list="${l.id}">${icon(l.icon)}<span>${esc(l.name)}</span></button>`).join("")}</div></div>`;document.body.append(modal);modal.querySelector("[data-close]").onclick=()=>modal.remove();modal.querySelectorAll("[data-pick-list]").forEach(x=>x.onclick=async()=>{try{await api(`/api/lists/${x.dataset.pickList}/items/${itemId}`,{method:"POST"});const l=state.lists.find(v=>String(v.id)===x.dataset.pickList);if(l)l.itemCount=Number(l.itemCount||0)+1;modal.remove();toast("Adicionado à lista e ao PugotiTasks.");render()}catch(error){toast(error.message)}})}
function libraryContent(items,searching){
  if(state.view.startsWith("list:")&&state.activeList)return customListContent();
  if(state.busy)return `<section class="grid"><div class="empty"><div class="loader"></div></div></section>`;
  if(searching)return `<div class="section-head"><h2>Catálogo</h2><span>${items.length} ${items.length===1?"resultado":"resultados"}</span></div><section class="grid">${items.length?items.map((x,index)=>card(x,true,index)).join(""):`<div class="empty">${icon("search_off")}<h3>Nenhum título encontrado</h3><p>Tente outro nome ou tipo de conteúdo.</p></div>`}</section>`;
  if(state.view==="planned")return plannedContent(items);
  if(state.view==="in_progress"||state.view==="following")return journeyContent(items,state.view);
  if(state.view==="games")return collectionSection("Jogos",items);
  if(state.view==="movies")return collectionSection("Filmes",items);
  if(state.view==="series")return collectionSection("Séries",items);
  if(state.view==="anime")return collectionSection("Animes",items);
  const games=items.filter(item=>itemCategory(item)==="game");
  const movies=items.filter(item=>itemCategory(item)==="movie");
  const series=items.filter(item=>itemCategory(item)==="tv");
  const anime=items.filter(item=>itemCategory(item)==="anime");
  return `<div class="split-library">${collectionSection("Jogos",games)}${collectionSection("Filmes",movies)}${collectionSection("Séries",series)}${collectionSection("Animes",anime)}${recommendationsSection()}</div>`;
}
function render(){closeReviewPreview();const items=state.results.length||state.query?state.results:filtered();const searching=Boolean(state.query);root.className="";root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon("auto_awesome")}</span>PugotiList</div><div class="nav-label">Descobrir</div><nav class="nav">${[["home","home","Início"],["games","sports_esports","Jogos"],["watch","movie","Filmes e séries"],["favorites","favorite","Favoritos"],["completed","verified","Concluídos"]].map(([v,i,l])=>`<button data-view="${v}" class="${state.view===v?"active":""}">${icon(i)}<span>${l}</span></button>`).join("")}</nav><div class="nav-label">Minha jornada</div><nav class="nav">${[["planned","bookmark","Quero conhecer"],["in_progress","play_circle","Em andamento"]].map(([v,i,l])=>`<button data-view="${v}" class="${state.view===v?"active":""}">${icon(i)}<span>${l}</span></button>`).join("")}</nav></aside><main class="main"><header class="topbar"><form class="search" id="search-form">${icon("search")}<input name="q" value="${esc(state.query)}" placeholder="Pesquisar jogos, filmes, séries e animes..." autocomplete="off"><select name="type"><option title="Atalho: /j" value="game" ${state.type==="game"?"selected":""}>Jogos</option><option title="Atalho: /f" value="movie" ${state.type==="movie"?"selected":""}>Filmes</option><option title="Atalho: /s" value="tv" ${state.type==="tv"?"selected":""}>Séries</option><option title="Atalho: /a" value="anime" ${state.type==="anime"?"selected":""}>Animes</option></select></form><div class="profile"><button style="all:unset" data-profile>${avatar()}</button>${state.profileOpen?`<div class="profile-menu"><strong>${esc(profileName())}</strong><small>@${esc(state.profile.username)}</small><small>Perfil compartilhado PugotiLab</small><a href="https://pugotilab.com/auth/profile?return=${encodeURIComponent(location.href)}">${icon("person")} Abrir perfil</a><a href="https://pugotilab.com/auth/logout?return=${encodeURIComponent(location.origin)}">${icon("logout")} Sair</a></div>`:""}</div></header>${state.detailsBusy||state.details?detailsModal():`<section class="hero"><div><span class="eyebrow">Sua coleção, sua história</span><h1>${searching?`Resultados para “${esc(state.query)}”`:"O que vem agora?"}</h1><p>${searching?"Escolha um título e deixe os detalhes por conta do PugotiList.":"Guarde o que quer jogar e assistir. Avalie o que já viveu."}</p></div><div class="stats"><div class="stat"><strong>${state.items.length}</strong><small>títulos</small></div><div class="stat"><strong>${state.items.filter(x=>x.favorite).length}</strong><small>favoritos</small></div></div></section>${searching&&!state.providers[state.type==="game"?"games":"movies"]?`<div class="notice">${icon("info")}O app está pronto; falta conectar a credencial central deste catálogo.</div>`:""}${libraryContent(items,searching)}<footer class="credits">Este produto utiliza a API do TMDB, mas não é endossado nem certificado pelo TMDB. <a href="https://www.themoviedb.org" target="_blank" rel="noreferrer">The Movie Database</a></footer>`}</main></div>`;bind();enhanceRenderedDom()}
function toast(message){const el=document.createElement("div");el.className="toast";el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2600)}
function bind(){document.onkeydown=event=>{if(event.ctrlKey||event.altKey||event.metaKey||event.target?.matches?.("input,textarea,select,[contenteditable=true]"))return;const shortcuts={"/j":"game","/f":"movie","/s":"tv","/a":"anime"};const type=shortcuts[event.key.toLowerCase()];if(!type)return;event.preventDefault();state.type=type;state.query="";state.results=[];state.details=null;render();requestAnimationFrame(()=>document.querySelector("#search-form input")?.focus())};document.querySelectorAll("[data-review-card]").forEach(card=>{const open=()=>{clearTimeout(reviewPreviewTimer);const item=state.items.find(entry=>String(entry.id)===card.dataset.reviewCard);if(item)reviewPreviewTimer=setTimeout(()=>showReviewPreview(item),1200)};card.addEventListener("mouseenter",open);card.addEventListener("mouseleave",closeReviewPreview);card.addEventListener("focusin",open);card.addEventListener("focusout",closeReviewPreview)});document.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.details=null;state.query="";state.results=[];render()});document.querySelector("[data-profile]").onclick=()=>{state.profileOpen=!state.profileOpen;render()};const searchInput=document.querySelector("#search-form input"),searchType=document.querySelector("#search-form select");searchInput.oninput=event=>{const shortcuts={"/j":"game","/f":"movie","/s":"tv","/a":"anime"};const type=shortcuts[event.currentTarget.value.trim().toLowerCase()];if(!type)return;state.type=type;event.currentTarget.value="";searchType.value=type};document.querySelector("#search-form").onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget);state.query=String(data.get("q")||"").trim();state.type=String(data.get("type")||"game");if(state.query.length<2)return toast("Digite pelo menos dois caracteres.");state.details=null;state.busy=true;render();try{const body=await api(`/api/search?q=${encodeURIComponent(state.query)}&type=${state.type}`);state.results=body.results}catch(error){toast(error.message);state.results=[]}finally{state.busy=false;render()}};document.querySelectorAll("[data-add-index]").forEach(b=>b.onclick=async()=>{const item=state.results[Number(b.dataset.addIndex)];if(!item)return toast("Esse título não está mais disponível na pesquisa.");try{const body=await api("/api/library",{method:"POST",body:JSON.stringify(item)});state.items=state.items.filter(existing=>!(existing.provider===item.provider&&(existing.external_id||existing.externalId)===item.externalId));state.items.unshift(body.item);toast("Adicionado à sua lista.");state.query="";state.results=[];render()}catch(error){toast(error.message)}});document.querySelector("[data-add-details]")?.addEventListener("click",async()=>{const d=state.details?.details;if(!d)return;try{const body=await api("/api/library",{method:"POST",body:JSON.stringify({provider:d.provider,mediaType:d.mediaType,externalId:d.externalId,title:d.title,posterUrl:d.posterUrl,releaseYear:d.releaseYear,creatorName:(d.developers||d.directors||[])[0]||"",contentCategory:d.contentCategory||d.mediaType})});state.items=state.items.filter(item=>!(item.provider===d.provider&&item.external_id===d.externalId));state.items.unshift(body.item);state.details.personal=body.item;toast("Adicionado à sua biblioteca.");render()}catch(error){toast(error.message)}});document.querySelector("[data-play-platform]")?.addEventListener("change",async event=>{const personal=state.details?.personal;if(!personal)return;event.currentTarget.disabled=true;try{const body=await api(`/api/library/${personal.id}`,{method:"PATCH",body:JSON.stringify({playPlatform:event.currentTarget.value})});const item=state.items.find(entry=>entry.id===body.item.id);if(item)Object.assign(item,body.item);state.details.personal=body.item;toast(body.item.play_platform?`Plataforma: ${platformLabels[body.item.play_platform]}`:"Plataforma removida.");render()}catch(error){event.currentTarget.disabled=false;toast(error.message)}});document.querySelector("[data-edit-review]")?.addEventListener("click",()=>{state.reviewEditing=true;render()});const reviewForm=document.querySelector("[data-review-form]");if(reviewForm){const reviewText=reviewForm.querySelector("textarea");reviewText.oninput=()=>{document.querySelector("[data-review-count]").textContent=`${reviewText.value.length}/600`};reviewForm.onsubmit=async event=>{event.preventDefault();const personal=state.details?.personal;if(!personal)return;const button=reviewForm.querySelector("button");button.disabled=true;try{const body=await api(`/api/library/${personal.id}`,{method:"PATCH",body:JSON.stringify({notes:reviewText.value.trim()})});const item=state.items.find(entry=>entry.id===body.item.id);if(item)Object.assign(item,body.item);state.details.personal=body.item;state.reviewEditing=false;toast("Review publicada.");render()}catch(error){button.disabled=false;toast(error.message)}}}document.querySelectorAll("[data-rating-id]").forEach(group=>group.querySelectorAll("[data-star]").forEach(star=>star.onclick=async event=>{const item=state.items.find(x=>String(x.id)===group.dataset.ratingId);if(!item)return;const rect=star.getBoundingClientRect();const half=event.clientX-rect.left<rect.width/2;const rating=Number(star.dataset.star)*2-(half?1:0);try{const body=await api(`/api/library/${item.id}`,{method:"PATCH",body:JSON.stringify({rating})});Object.assign(item,body.item);if(state.details?.personal?.id===body.item.id)state.details.personal=body.item;toast(`Nota: ${(rating/2).toLocaleString("pt-BR")} estrelas`);render()}catch(error){toast(error.message)}}));document.querySelectorAll("[data-favorite]").forEach(b=>b.onclick=async()=>{const item=state.items.find(x=>String(x.id)===b.dataset.favorite);if(!item)return;try{const body=await api(`/api/library/${item.id}`,{method:"PATCH",body:JSON.stringify({favorite:!item.favorite})});Object.assign(item,body.item);render()}catch(error){toast(error.message)}});document.querySelectorAll("[data-details-id]").forEach(b=>b.onclick=async()=>{state.detailsBusy=true;state.details=null;state.reviewEditing=false;render();try{state.details=await api(`/api/details?provider=${encodeURIComponent(b.dataset.detailsProvider)}&type=${encodeURIComponent(b.dataset.detailsType)}&id=${encodeURIComponent(b.dataset.detailsId)}`)}catch(error){toast(error.message)}finally{state.detailsBusy=false;render()}});document.querySelector("[data-close-details]")?.addEventListener("click",()=>{state.details=null;render()});document.querySelector("[data-overlay]")?.addEventListener("click",e=>{if(e.target===e.currentTarget){state.details=null;render()}})}
async function boot(){try{const data=await api("/api/bootstrap");Object.assign(state,data);labels.in_progress="Jogando agora";state.recommendationsBusy=true;render();hydrateWorkSituations();api("/api/recommendations").then(body=>{state.recommendations={games:body.games||[],movies:body.movies||[],series:body.series||[],anime:body.anime||[]};state.recommendationBasis=body.basedOn||{}}).catch(()=>{}).finally(()=>{state.recommendationsBusy=false;render()})}catch(error){if(error.status===401){const back=encodeURIComponent(location.href);root.className="center";root.innerHTML=`<div class="login"><span class="brand-mark">${icon("auto_awesome")}</span><h1>PugotiList</h1><p>Jogos, filmes e séries organizados com sua conta e seu perfil PugotiLab.</p><a class="primary" href="${esc(error.loginUrl||"https://pugotilab.com/auth")}?return=${back}">${icon("login")} Entrar com PugotiLab</a></div>`}else root.textContent=error.message}}
async function syncTasksState(){if(document.hidden||!state.profile)return;try{const body=await api("/api/sync/tasks",{method:"POST"});if(body.changed){state.items=body.items;if(state.activeList)state.activeList=await api(`/api/lists/${state.activeList.list.id}`);toast(`${body.changed} obra${body.changed===1?"":"s"} sincronizada${body.changed===1?"":"s"} com o PugotiTasks.`);render()}}catch{}}
setInterval(syncTasksState,30000);document.addEventListener("visibilitychange",()=>{if(!document.hidden)syncTasksState()});
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&(state.details||state.detailsBusy)){state.details=null;state.detailsBusy=false;render()}});
boot();
